{
  "business_linkages": [],
  "business_linkage_gap": "Costco 披露電商與倉庫並行營運，但未揭露線上訂單由哪些倉庫履約、是否排擠店內銷售，或兩個通路之間有何資本與人力調度。電商與全公司增速差無法檢驗這些傳導，需有通路銷售移轉或履約配置的公開資料。",
  "hypotheses": [
    {
      "stance": "bull",
      "mechanism": "首季業績顯示，排除油價與匯率後，電商可比銷售年增 13.2%，高於全公司的 7.1%。若八個市場的既有電商網站持續帶來新增消費，相較於線上銷售僅隨公司整體成長的基準，電商可拉高整體銷售增速。電商銷售占比、來自倉庫通路的移轉額及履約成本均未知，無法估算增量獲利。",
      "target": "Costco",
      "horizon": "2025-12-31",
      "catalyst": "2024-12-12 公布首季實績後，以 Costco 投資人關係網站的 2025 財年第二季業績公告檢驗電商領先幅度，最遲於 2025-12-31 覆核。",
      "prediction": "第二季調整後電商可比銷售年增率高於全公司同口徑年增率，差距至少維持首季的 6.1 個百分點。此指標可檢驗電商相對動能，無法辨認新增消費。",
      "invalidation": "Costco 公布的第二季調整後電商可比銷售年增率減全公司同口徑年增率，低於 6.1 個百分點。",
      "claim_ids": ["fact:costco-release:adjusted", "fact:costco-release:footprint"]
    },
    {
      "stance": "bear",
      "mechanism": "首季全公司可比銷售年增 5.2%，較排除油價與匯率後的 7.1% 低 1.9 個百分點。若油價或匯率的合計拖累加深，即使調整後增速持平，較低的加油站售價或海外銷售換算金額仍會壓低美元計價的可比銷售增速。財報揭示這項曝險，未提供兩因素各自的金額或毛利效果。",
      "target": "Costco",
      "horizon": "2025-12-31",
      "catalyst": "以 2024-12-12 公布的首季差距為基準，於 Costco 投資人關係網站公布 2025 財年第二季業績後比對兩種口徑，最遲於 2025-12-31 覆核。",
      "prediction": "第二季全公司調整後可比銷售年增率減未調整年增率，大於首季的 1.9 個百分點，顯示油價與匯率對公布增速的合計拖累擴大。",
      "invalidation": "Costco 公布的第二季全公司調整後可比銷售年增率減未調整年增率，小於或等於 1.9 個百分點。",
      "claim_ids": ["fact:costco-release:adjusted", "fact:costco-release:comps"]
    }
  ],
  "assessment": {
    "thesis": "Costco 的 2025 財年首季實績顯示電商銷售成長領先整體，但油價與匯率已拉低全公司公布的可比銷售增速，兩者對獲利的影響仍待量化。",
    "key_gap": "電商成長有多少來自會員新增消費，又有多少來自原本會在倉庫完成的交易？缺少通路銷售占比與履約成本，即使電商持續領先，也無法判定其增量獲利。",
    "next_check": "首個覆核窗口為 Costco 公布 2025 財年第二季業績時。依首季公告口徑，核對調整後電商與全公司的可比銷售增速差，以及全公司調整前後的增速差。這兩項比較可用公開資料完成；若無新增揭露，量化通路移轉與履約獲利仍需非公開交易及成本紀錄。以下次季預測均為研究情境，公司未在所附資料中提供相關指引。",
    "evidence_limits": [
      {
        "evidence_id": "costco-release:adjusted",
        "limit": "支持首季調整後全公司增長 7.1%、電商增長 13.2%；缺少電商銷售權重，無法換算其對整體成長的貢獻。"
      },
      {
        "evidence_id": "costco-release:comps",
        "limit": "支持首季未調整全公司與各地區可比銷售年增率，以及電商年增 13.0%；搭配調整後數字只能衡量油價與匯率的合計差異。"
      },
      {
        "evidence_id": "costco-release:footprint",
        "limit": "支持 897 個倉庫與八個電商市場的營運範圍；無法據此認定倉庫承接線上履約或兩通路間已發生銷售移轉。"
      },
      {
        "evidence_id": "costco-release:original",
        "limit": "同一公告的英文摘句確認當時營運 897 個倉庫；單一時點的據點數無法衡量新增產能或展店效益。"
      }
    ],
    "public_checks": [
      {
        "metric": "調整後電商可比銷售年增率減全公司同口徑年增率",
        "source_to_watch": "Costco 投資人關係網站季度業績公告的調整後可比銷售表",
        "window": "2025 財年第二季，於該季業績公布後覆核",
        "impact_on_thesis": "差距達首季的 6.1 個百分點或以上，支持電商持續領先；低於此值則削弱多方案例。此為相對動能代理指標，不能歸因至新增消費或獲利。",
        "evidence_ids": ["costco-release:adjusted"]
      },
      {
        "metric": "全公司調整後可比銷售年增率減未調整年增率",
        "source_to_watch": "Costco 投資人關係網站季度業績公告的可比銷售表與排除油價、匯率後的比較表",
        "window": "2025 財年第二季，於該季業績公布後覆核",
        "impact_on_thesis": "差距超過首季的 1.9 個百分點，支持公布銷售增速承受更大拖累；持平或縮小則推翻拖累擴大的預測。差距無法分拆油價、匯率或推算毛利。",
        "evidence_ids": ["costco-release:adjusted", "costco-release:comps"]
      }
    ],
    "supply_chain": [],
    "trade_opportunities": []
  }
}
